    f(e, args);

    uint256 wavaxAllocatedAfter = avaxAllocated();

    assert wavaxAllocatedBefore == wavaxAllocatedAfter, "not yet implemented";
}"

"rule cl_lp_supply_fixed(method f, env e) {
